{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Launch template root block device is not encrypted",
      "resource": "aws_launch_template.web_app",
      "severity": "MEDIUM",
      "explanation": "The launch template does not specify an encryption setting for the root block device, meaning instances launched from it may have unencrypted EBS volumes."
    },
    {
      "check_id": "AVD-AWS-0130",
      "title": "IMDSv2 (token requirement) is not enforced",
      "resource": "aws_launch_template.web_app",
      "severity": "HIGH",
      "explanation": "The metadata options are not configured to require HTTP tokens, allowing potential SSRF attacks against the Instance Metadata Service (IMDS)."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Hardcoded secrets in user_data",
      "resource": "aws_launch_template.web_app",
      "severity": "CRITICAL",
      "explanation": "The API key 'sk-1234567890abcdef' is hardcoded directly in the user_data script, exposing sensitive credentials in plain text within the Terraform state and instance metadata."
    }
  ],
  "patched_code": "resource "aws_launch_template" "web_app" {
  name_prefix   = "automated-employee-onboarding-platform-lt-web-"
  image_id      = data.aws_ami.ubuntu.id
  instance_type = var.instance_type
  key_name      = var.key_pair_name
  vpc_security_group_ids = [aws_security_group.web_app.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  block_device_mappings {
    device_name = "/dev/sda1"
    ebs {
      encrypted = true
    }
  }

  user_data = base64encode(<<-EOF
              export DATABASE_PASSWORD="${var.db_password}"
              apt-get update
              apt-get install -y nginx nodejs npm
              systemctl start nginx
              systemctl enable nginx
              EOF
  )
  tag_specifications {
    resource_type = "instance"
  }
}",
  "fix_summary": "Added `metadata_options` to enforce IMDSv2 (`http_tokens = "required"`) and `block_device_mappings` to enable EBS encryption. Removed the hardcoded API key from `user_data` as it constitutes a critical secret exposure; this value should be managed via AWS Secrets Manager or SSM Parameter Store instead."
}
